20250305110000	{"-- Suppression des politiques existantes pour team_members\nDROP POLICY IF EXISTS \\"team_members_select_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_insert_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_update_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_update_own_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_delete_policy\\" ON public.team_members","-- Création d'une politique de sélection pour team_members sans récursion\nCREATE POLICY \\"team_members_select_policy\\" \nON public.team_members FOR SELECT \nUSING (\n  -- Permet à l'utilisateur de voir ses propres enregistrements\n  user_id = auth.uid()\n  -- Ou les enregistrements des équipes qu'il a créées\n  OR team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","-- Création d'une politique d'insertion pour team_members\nCREATE POLICY \\"team_members_insert_policy\\" \nON public.team_members FOR INSERT \nWITH CHECK (\n  -- Permet à l'utilisateur d'insérer des membres dans les équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","-- Création d'une politique de mise à jour pour team_members\nCREATE POLICY \\"team_members_update_policy\\" \nON public.team_members FOR UPDATE \nUSING (\n  -- Permet à l'utilisateur de mettre à jour les membres des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","-- Création d'une politique de mise à jour pour ses propres enregistrements\nCREATE POLICY \\"team_members_update_own_policy\\" \nON public.team_members FOR UPDATE \nUSING (user_id = auth.uid())","-- Création d'une politique de suppression pour team_members\nCREATE POLICY \\"team_members_delete_policy\\" \nON public.team_members FOR DELETE \nUSING (\n  -- Permet à l'utilisateur de supprimer des membres des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)"}	fix_team_members_policies
20250305104200	{"-- Ce script est destiné à être exécuté directement dans la console SQL de Supabase\n-- pour corriger toutes les politiques RLS liées aux équipes\n\n-- 1. Suppression de toutes les politiques existantes qui pourraient causer des récursions\n-- Pour la table teams\nDROP POLICY IF EXISTS \\"teams_select_policy\\" ON public.teams","DROP POLICY IF EXISTS \\"teams_insert_policy\\" ON public.teams","DROP POLICY IF EXISTS \\"teams_update_policy\\" ON public.teams","DROP POLICY IF EXISTS \\"teams_delete_policy\\" ON public.teams","-- Pour la table team_members\nDROP POLICY IF EXISTS \\"team_members_select_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_insert_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_update_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_update_own_policy\\" ON public.team_members","DROP POLICY IF EXISTS \\"team_members_delete_policy\\" ON public.team_members","-- Pour la table team_projects\nDROP POLICY IF EXISTS \\"team_projects_select_policy\\" ON public.team_projects","DROP POLICY IF EXISTS \\"team_projects_insert_policy\\" ON public.team_projects","DROP POLICY IF EXISTS \\"team_projects_delete_policy\\" ON public.team_projects","-- 2. Création de nouvelles politiques sans récursion\n-- Pour la table teams\nCREATE POLICY \\"teams_select_policy\\" \nON public.teams FOR SELECT \nUSING (\n  -- Permet à l'utilisateur de voir les équipes qu'il a créées\n  created_by = auth.uid()\n)","CREATE POLICY \\"teams_insert_policy\\" \nON public.teams FOR INSERT \nWITH CHECK (created_by = auth.uid())","CREATE POLICY \\"teams_update_policy\\" \nON public.teams FOR UPDATE \nUSING (created_by = auth.uid())","CREATE POLICY \\"teams_delete_policy\\" \nON public.teams FOR DELETE \nUSING (created_by = auth.uid())","-- Pour la table team_members\nCREATE POLICY \\"team_members_select_policy\\" \nON public.team_members FOR SELECT \nUSING (\n  -- Permet à l'utilisateur de voir ses propres enregistrements\n  user_id = auth.uid()\n  -- Ou les enregistrements des équipes qu'il a créées\n  OR team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","CREATE POLICY \\"team_members_insert_policy\\" \nON public.team_members FOR INSERT \nWITH CHECK (\n  -- Permet à l'utilisateur d'insérer des membres dans les équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","CREATE POLICY \\"team_members_update_policy\\" \nON public.team_members FOR UPDATE \nUSING (\n  -- Permet à l'utilisateur de mettre à jour les membres des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","CREATE POLICY \\"team_members_update_own_policy\\" \nON public.team_members FOR UPDATE \nUSING (user_id = auth.uid())","CREATE POLICY \\"team_members_delete_policy\\" \nON public.team_members FOR DELETE \nUSING (\n  -- Permet à l'utilisateur de supprimer des membres des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","-- Pour la table team_projects\nCREATE POLICY \\"team_projects_select_policy\\" \nON public.team_projects FOR SELECT \nUSING (\n  -- Permet à l'utilisateur de voir les projets des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n  -- Ou les projets des équipes auxquelles il appartient\n  OR team_id IN (\n    SELECT team_id FROM public.team_members WHERE user_id = auth.uid() AND status = 'active'\n  )\n)","CREATE POLICY \\"team_projects_insert_policy\\" \nON public.team_projects FOR INSERT \nWITH CHECK (\n  -- Permet à l'utilisateur d'insérer des projets dans les équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)","CREATE POLICY \\"team_projects_delete_policy\\" \nON public.team_projects FOR DELETE \nUSING (\n  -- Permet à l'utilisateur de supprimer des projets des équipes qu'il a créées\n  team_id IN (\n    SELECT id FROM public.teams WHERE created_by = auth.uid()\n  )\n)"}	fix_team_policies
20250305104900	{"-- Ce fichier est obsolète car nous n'avons pas de table public.users\n-- Nous utilisons la table auth.users qui est gérée par Supabase\n\n-- Cette migration est vide et peut être ignorée"}	fix_users_policy
20250305144500	{"-- Ce script corrige les politiques RLS pour la table invitations\n-- pour éviter d'accéder directement à auth.users\n\n-- Supprimer la politique existante qui cause l'erreur de permission\nDROP POLICY IF EXISTS \\"invitations_select_received_policy\\" ON public.invitations","-- Créer une nouvelle politique qui utilise auth.jwt() au lieu d'accéder directement à auth.users\nCREATE POLICY \\"invitations_select_received_policy\\" \nON public.invitations FOR SELECT \nUSING (\n  -- Utiliser le claim email du JWT au lieu d'accéder à auth.users\n  email = (SELECT coalesce(nullif(current_setting('request.jwt.claim.email', true), ''), \n                          nullif(current_setting('request.jwt.claims.email', true), ''))\n          )\n)"}	fix_invitations_policy
20250305150100	{"-- Ce script crée une table profiles pour stocker les informations publiques des utilisateurs\n-- et configure les déclencheurs nécessaires pour maintenir les données synchronisées\n\n-- Fonction pour gérer l'insertion automatique dans profiles lors de la création d'un utilisateur\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER AS $$\nBEGIN\n  INSERT INTO public.profiles (id, email, display_name, avatar_url, updated_at)\n  VALUES (new.id, new.email, COALESCE(new.raw_user_meta_data->>'display_name', new.email), new.raw_user_meta_data->>'avatar_url', now());\n  RETURN new;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","-- Créer la table profiles si elle n'existe pas\nCREATE TABLE IF NOT EXISTS public.profiles (\n  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  email TEXT NOT NULL,\n  display_name TEXT,\n  avatar_url TEXT,\n  bio TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- Ajouter un index sur l'email pour les recherches rapides\nCREATE INDEX IF NOT EXISTS profiles_email_idx ON public.profiles(email)","-- Activer la sécurité au niveau des lignes (RLS)\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY","-- Supprimer le déclencheur s'il existe déjà pour éviter les doublons\nDROP TRIGGER IF EXISTS on_auth_user_created ON auth.users","-- Créer un déclencheur pour insérer un profil lorsqu'un nouvel utilisateur est créé\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user()","-- Politiques RLS pour la table profiles\n\n-- Politique pour permettre à tous les utilisateurs authentifiés de voir les profils\nCREATE POLICY \\"profiles_select_policy\\" \nON public.profiles FOR SELECT \nUSING (auth.role() = 'authenticated')","-- Politique pour permettre aux utilisateurs de mettre à jour uniquement leur propre profil\nCREATE POLICY \\"profiles_update_policy\\" \nON public.profiles FOR UPDATE \nUSING (id = auth.uid())","-- Insérer les profils pour les utilisateurs existants si nécessaire\nINSERT INTO public.profiles (id, email, display_name, avatar_url, updated_at)\nSELECT \n  id, \n  email, \n  COALESCE(raw_user_meta_data->>'display_name', email),\n  raw_user_meta_data->>'avatar_url',\n  now()\nFROM auth.users\nON CONFLICT (id) DO NOTHING"}	add_profiles_table
20250305150400	{"-- Ce script corrige la relation entre team_members et profiles\n\n-- Supprimer d'abord l'ancienne contrainte de clé étrangère si elle existe\nALTER TABLE IF EXISTS public.team_members\nDROP CONSTRAINT IF EXISTS team_members_user_id_fkey","-- Ajouter une nouvelle contrainte de clé étrangère qui pointe à la fois vers auth.users et profiles\n-- Note: on peut avoir plusieurs contraintes sur la même colonne\nALTER TABLE public.team_members\nADD CONSTRAINT team_members_user_id_profiles_fkey\nFOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE","-- Recréer la contrainte originale vers auth.users si nécessaire\nALTER TABLE public.team_members\nADD CONSTRAINT team_members_user_id_auth_users_fkey\nFOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE","-- Pour être sûr, on rafraîchit le cache de schéma de Supabase\nNOTIFY pgrst, 'reload schema'"}	fix_team_members_profiles_relation
20250305230400	{"-- Ce script ajoute des politiques RLS pour la table des invitations\n-- afin de permettre à tous les utilisateurs de récupérer une invitation par son token\n\n-- Supprimer la politique existante si elle existe\nDROP POLICY IF EXISTS \\"Allow users to select invitations by token\\" ON public.invitations","-- Créer une nouvelle politique qui permet à n'importe quel utilisateur authentifié\n-- de voir une invitation en utilisant son token\nCREATE POLICY \\"Allow users to select invitations by token\\" \nON public.invitations FOR SELECT \nUSING (auth.role() = 'authenticated')"}	fix_invitation_policies
20250305230900	{"-- Ce script ajoute des politiques RLS pour permettre aux utilisateurs\n-- de modifier les invitations et les membres d'équipe\n\n-- Supprimer les politiques existantes si elles existent\nDROP POLICY IF EXISTS \\"Allow users to update invitations\\" ON public.invitations","DROP POLICY IF EXISTS \\"Allow users to insert team members\\" ON public.team_members","-- Créer une politique qui permet à n'importe quel utilisateur authentifié\n-- de mettre à jour une invitation (pour changer son statut)\nCREATE POLICY \\"Allow users to update invitations\\" \nON public.invitations FOR UPDATE\nUSING (auth.role() = 'authenticated')","-- Créer une politique qui permet à n'importe quel utilisateur authentifié\n-- d'insérer un nouveau membre d'équipe (pour rejoindre une équipe)\nCREATE POLICY \\"Allow users to insert team members\\" \nON public.team_members FOR INSERT\nWITH CHECK (auth.role() = 'authenticated')","-- Politique pour permettre la mise à jour des membres d'équipe\nDROP POLICY IF EXISTS \\"Allow users to update team members\\" ON public.team_members","CREATE POLICY \\"Allow users to update team members\\" \nON public.team_members FOR UPDATE\nUSING (auth.role() = 'authenticated')"}	fix_invitation_update_policies
20250305231400	{"-- Migration temporaire avec des politiques très permissives pour les tests\n-- AVERTISSEMENT: Ne pas utiliser en production telles quelles !\n\n-- Politiques très permissives pour auth.users\nDROP POLICY IF EXISTS \\"Temporary allow all operations on users\\" ON auth.users","CREATE POLICY \\"Temporary allow all operations on users\\" \nON auth.users FOR ALL\nUSING (true)","-- Politiques très permissives pour toutes les autres tables importantes\n-- Invitations\nDROP POLICY IF EXISTS \\"Temporary allow all operations on invitations\\" ON public.invitations","CREATE POLICY \\"Temporary allow all operations on invitations\\" \nON public.invitations FOR ALL\nUSING (true)","-- Team Members\nDROP POLICY IF EXISTS \\"Temporary allow all operations on team_members\\" ON public.team_members","CREATE POLICY \\"Temporary allow all operations on team_members\\" \nON public.team_members FOR ALL\nUSING (true)","-- Teams\nDROP POLICY IF EXISTS \\"Temporary allow all operations on teams\\" ON public.teams","CREATE POLICY \\"Temporary allow all operations on teams\\" \nON public.teams FOR ALL\nUSING (true)","-- Profiles\nDROP POLICY IF EXISTS \\"Temporary allow all operations on profiles\\" ON public.profiles","CREATE POLICY \\"Temporary allow all operations on profiles\\" \nON public.profiles FOR ALL\nUSING (true)","-- S'assurer que RLS est activé pour toutes ces tables\nALTER TABLE public.invitations ENABLE ROW LEVEL SECURITY","ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY","ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY","ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY"}	temporary_permissive_policies
20250306091336	{"-- Supprimer d'abord les politiques existantes qui pourraient référencer la colonne members\nDROP POLICY IF EXISTS \\"Users can view their own projects\\" ON public.projects","DROP POLICY IF EXISTS \\"Users can update their own projects\\" ON public.projects","DROP POLICY IF EXISTS \\"Users can delete their own projects\\" ON public.projects","-- Si la colonne members existe, mettre à jour pour ajouter une valeur par défaut et la rendre nullable\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_name = 'projects'\n    AND column_name = 'members'\n  ) THEN\n    -- Mettre à jour la colonne pour la rendre nullable et avec une valeur par défaut\n    ALTER TABLE public.projects ALTER COLUMN members SET DEFAULT '{}';\n    ALTER TABLE public.projects ALTER COLUMN members DROP NOT NULL;\n  END IF;\nEND $$","-- Créer les nouvelles politiques RLS pour les projets\nCREATE POLICY \\"Users can view their own projects or team projects\\" ON public.projects\n  FOR SELECT USING (\n    auth.uid() = created_by OR\n    EXISTS (\n      SELECT 1 FROM team_projects tp\n      JOIN team_members tm ON tp.team_id = tm.team_id\n      WHERE tp.project_id = projects.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    )\n  )","CREATE POLICY \\"Users can update their own projects or team projects\\" ON public.projects\n  FOR UPDATE USING (\n    auth.uid() = created_by OR\n    EXISTS (\n      SELECT 1 FROM team_projects tp\n      JOIN team_members tm ON tp.team_id = tm.team_id\n      WHERE tp.project_id = projects.id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )","CREATE POLICY \\"Users can delete their own projects or team projects\\" ON public.projects\n  FOR DELETE USING (\n    auth.uid() = created_by OR\n    EXISTS (\n      SELECT 1 FROM team_projects tp\n      JOIN team_members tm ON tp.team_id = tm.team_id\n      WHERE tp.project_id = projects.id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )"}	remove_members_column
20250306093148	{"-- Créer une nouvelle table pour associer les tâches aux équipes\nCREATE TABLE IF NOT EXISTS public.team_tasks (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  team_id UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,\n  task_id UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,\n  UNIQUE(team_id, task_id)\n)","-- Activer la sécurité au niveau des lignes (RLS)\nALTER TABLE public.team_tasks ENABLE ROW LEVEL SECURITY","-- Créer les politiques RLS pour la table team_tasks\n-- Politique pour voir les tâches des équipes: un utilisateur peut voir les tâches assignées à ses équipes\nCREATE POLICY \\"Users can view their team tasks\\" ON public.team_tasks\n  FOR SELECT USING (\n    EXISTS (\n      SELECT 1 FROM team_members tm\n      WHERE tm.team_id = team_tasks.team_id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    )\n  )","-- Politique pour créer des tâches pour les équipes: un utilisateur peut assigner une tâche à son équipe s'il est admin\nCREATE POLICY \\"Team admins can assign tasks to their teams\\" ON public.team_tasks\n  FOR INSERT WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM team_members tm\n      WHERE tm.team_id = team_tasks.team_id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )","-- Politique pour supprimer des tâches des équipes: un utilisateur peut supprimer une tâche de son équipe s'il est admin\nCREATE POLICY \\"Team admins can remove tasks from their teams\\" ON public.team_tasks\n  FOR DELETE USING (\n    EXISTS (\n      SELECT 1 FROM team_members tm\n      WHERE tm.team_id = team_tasks.team_id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )","-- Mettre à jour la colonne assignedTo pour qu'elle soit nullable\nALTER TABLE public.tasks ALTER COLUMN assigned_to DROP NOT NULL","ALTER TABLE public.tasks ALTER COLUMN assigned_to SET DEFAULT NULL","-- Supprimer les politiques existantes sur la table des tâches\nDROP POLICY IF EXISTS \\"Users can view their assigned tasks\\" ON public.tasks","DROP POLICY IF EXISTS \\"Users can update their assigned tasks\\" ON public.tasks","DROP POLICY IF EXISTS \\"Users can delete their own tasks\\" ON public.tasks","-- Mettre à jour les politiques RLS pour la table des tâches\n-- Permettre aux utilisateurs de voir les tâches qui leur sont assignées individuellement OU via leurs équipes\nCREATE POLICY \\"Users can view their assigned tasks or team tasks\\" ON public.tasks\n  FOR SELECT USING (\n    assigned_to = auth.uid()::text OR\n    created_by = auth.uid() OR\n    EXISTS (\n      SELECT 1 FROM team_tasks tt\n      JOIN team_members tm ON tt.team_id = tm.team_id\n      WHERE tt.task_id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    )\n  )","-- Permettre aux utilisateurs de mettre à jour les tâches qui leur sont assignées individuellement OU via leurs équipes (s'ils sont admin)\nCREATE POLICY \\"Users can update their assigned tasks or team tasks\\" ON public.tasks\n  FOR UPDATE USING (\n    assigned_to = auth.uid()::text OR\n    created_by = auth.uid() OR\n    EXISTS (\n      SELECT 1 FROM team_tasks tt\n      JOIN team_members tm ON tt.team_id = tm.team_id\n      WHERE tt.task_id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )","-- Permettre aux utilisateurs de supprimer les tâches qu'ils ont créées OU les tâches des équipes dont ils sont admins\nCREATE POLICY \\"Users can delete their own tasks or team tasks\\" ON public.tasks\n  FOR DELETE USING (\n    created_by = auth.uid() OR\n    EXISTS (\n      SELECT 1 FROM team_tasks tt\n      JOIN team_members tm ON tt.team_id = tm.team_id\n      WHERE tt.task_id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.role = 'admin'\n      AND tm.status = 'active'\n    )\n  )"}	task_team_assignment
20250306104800	{"-- Correction des politiques d'insertion pour les tâches\n-- Permettre aux utilisateurs d'insérer des tâches et de les assigner à des membres d'équipe ou à des équipes\n\n-- Vérifier et créer la politique d'insertion manquante\nDROP POLICY IF EXISTS \\"Users can insert tasks\\" ON public.tasks","CREATE POLICY \\"Users can insert tasks\\" ON public.tasks\n  FOR INSERT WITH CHECK (\n    -- L'utilisateur peut toujours créer une tâche\n    -- La tâche peut être assignée à l'utilisateur lui-même, à un autre membre de l'équipe, ou à personne (si assignée à une équipe)\n    created_by = auth.uid() AND\n    (\n      -- Assignée à personne (car assignée à une équipe)\n      assigned_to IS NULL OR\n      \n      -- Assignée à l'utilisateur lui-même\n      assigned_to = auth.uid()::text OR\n      \n      -- Assignée à un autre membre d'une équipe dont l'utilisateur est admin\n      EXISTS (\n        SELECT 1 FROM team_members tm\n        JOIN team_members current_user_tm ON tm.team_id = current_user_tm.team_id\n        WHERE tm.user_id::text = assigned_to\n        AND current_user_tm.user_id = auth.uid()\n        AND current_user_tm.role = 'admin'\n        AND tm.status = 'active'\n        AND current_user_tm.status = 'active'\n      )\n    )\n  )","-- Mettre à jour la politique de sélection pour prendre en compte les projets\nDROP POLICY IF EXISTS \\"Users can view their assigned tasks or team tasks\\" ON public.tasks","CREATE POLICY \\"Users can view their assigned tasks or team tasks\\" ON public.tasks\n  FOR SELECT USING (\n    -- Assignée directement à l'utilisateur\n    assigned_to = auth.uid()::text OR\n    \n    -- Créée par l'utilisateur\n    created_by = auth.uid() OR\n    \n    -- Associée à une équipe dont l'utilisateur est membre\n    EXISTS (\n      SELECT 1 FROM team_tasks tt\n      JOIN team_members tm ON tt.team_id = tm.team_id\n      WHERE tt.task_id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    ) OR\n    \n    -- Associée à un projet où l'utilisateur est membre d'une équipe\n    EXISTS (\n      SELECT 1 FROM public.tasks t\n      JOIN public.projects p ON t.project_id = p.id\n      JOIN public.team_projects tp ON p.id = tp.project_id\n      JOIN public.team_members tm ON tp.team_id = tm.team_id\n      WHERE t.id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    )\n  )"}	fix_tasks_insert_policy
20250306105000	{"-- Correction des politiques d'insertion pour les tâches (correction de la récursion infinie)\n-- Permettre aux utilisateurs d'insérer des tâches et de les assigner à des membres d'équipe ou à des équipes\n\n-- Vérifier et créer la politique d'insertion manquante\nDROP POLICY IF EXISTS \\"Users can insert tasks\\" ON public.tasks","CREATE POLICY \\"Users can insert tasks\\" ON public.tasks\n  FOR INSERT WITH CHECK (\n    -- L'utilisateur peut toujours créer une tâche\n    -- La tâche peut être assignée à l'utilisateur lui-même, à un autre membre de l'équipe, ou à personne (si assignée à une équipe)\n    created_by = auth.uid() AND\n    (\n      -- Assignée à personne (car assignée à une équipe)\n      assigned_to IS NULL OR\n      \n      -- Assignée à l'utilisateur lui-même\n      assigned_to = auth.uid()::text OR\n      \n      -- Assignée à un autre membre d'une équipe dont l'utilisateur est admin\n      EXISTS (\n        SELECT 1 FROM team_members tm\n        JOIN team_members current_user_tm ON tm.team_id = current_user_tm.team_id\n        WHERE tm.user_id::text = assigned_to\n        AND current_user_tm.user_id = auth.uid()\n        AND current_user_tm.role = 'admin'\n        AND tm.status = 'active'\n        AND current_user_tm.status = 'active'\n      )\n    )\n  )","-- Mettre à jour la politique de sélection pour prendre en compte les projets\nDROP POLICY IF EXISTS \\"Users can view their assigned tasks or team tasks\\" ON public.tasks","CREATE POLICY \\"Users can view their assigned tasks or team tasks\\" ON public.tasks\n  FOR SELECT USING (\n    -- Assignée directement à l'utilisateur\n    assigned_to = auth.uid()::text OR\n    \n    -- Créée par l'utilisateur\n    created_by = auth.uid() OR\n    \n    -- Associée à une équipe dont l'utilisateur est membre\n    EXISTS (\n      SELECT 1 FROM team_tasks tt\n      JOIN team_members tm ON tt.team_id = tm.team_id\n      WHERE tt.task_id = tasks.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    ) OR\n    \n    -- Associée à un projet où l'utilisateur est membre d'une équipe\n    EXISTS (\n      SELECT 1 FROM projects p\n      JOIN team_projects tp ON p.id = tp.project_id\n      JOIN team_members tm ON tp.team_id = tm.team_id\n      WHERE tasks.project_id = p.id\n      AND tm.user_id = auth.uid()\n      AND tm.status = 'active'\n    )\n  )"}	fix_tasks_insert_policy_recursive
20250306123100	{"-- Création de la table d'historique des tâches\nCREATE TABLE IF NOT EXISTS task_history (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES auth.users(id),\n  field_name TEXT NOT NULL,\n  old_value TEXT,\n  new_value TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,\n  CONSTRAINT task_history_task_id_fk FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE\n)","-- Index pour accélérer les recherches par tâche\nCREATE INDEX IF NOT EXISTS task_history_task_id_idx ON task_history(task_id)","-- Politique RLS pour permettre à tous les utilisateurs authentifiés de voir l'historique des tâches auxquelles ils ont accès\nCREATE POLICY \\"Users can view task history if they can view the task\\" ON task_history\n  FOR SELECT USING (\n    auth.uid()::text IN (\n      SELECT created_by::text FROM tasks WHERE id = task_id\n      UNION\n      SELECT assigned_to FROM tasks WHERE id = task_id AND assigned_to IS NOT NULL\n      UNION\n      SELECT tm.user_id::text FROM team_members tm\n      JOIN team_tasks tt ON tm.team_id = tt.team_id\n      WHERE tt.task_id = task_id\n      UNION\n      SELECT tm.user_id::text FROM team_members tm\n      JOIN team_projects tp ON tm.team_id = tp.team_id\n      JOIN tasks t ON tp.project_id = t.project_id\n      WHERE t.id = task_id\n    )\n  )","-- Politique RLS pour permettre aux utilisateurs authentifiés d'insérer des entrées d'historique pour les tâches qu'ils peuvent modifier\nCREATE POLICY \\"Users can insert task history if they can modify the task\\" ON task_history\n  FOR INSERT WITH CHECK (\n    auth.uid()::text = user_id::text AND\n    auth.uid()::text IN (\n      SELECT created_by::text FROM tasks WHERE id = task_id\n      UNION\n      SELECT assigned_to FROM tasks WHERE id = task_id AND assigned_to IS NOT NULL\n      UNION\n      SELECT tm.user_id::text FROM team_members tm\n      JOIN team_tasks tt ON tm.team_id = tt.team_id\n      WHERE tt.task_id = task_id\n      UNION\n      SELECT tm.user_id::text FROM team_members tm\n      JOIN team_projects tp ON tm.team_id = tp.team_id\n      JOIN tasks t ON tp.project_id = t.project_id\n      WHERE t.id = task_id\n    )\n  )","-- Activer la sécurité au niveau des lignes (RLS)\nALTER TABLE task_history ENABLE ROW LEVEL SECURITY"}	create_task_history
20250316114646	{"-- Création de la table des notifications\nCREATE TABLE IF NOT EXISTS public.notifications (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    title TEXT NOT NULL,\n    message TEXT NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,\n    is_read BOOLEAN DEFAULT false NOT NULL,\n    type TEXT NOT NULL,\n    related_id UUID,\n    user_id UUID REFERENCES auth.users(id),\n    CONSTRAINT notifications_type_check CHECK (\n        type IN (\n            'projectCreated', 'projectStatusChanged', 'projectBudgetAlert',\n            'phaseCreated', 'phaseStatusChanged',\n            'taskAssigned', 'taskDueSoon', 'taskOverdue', 'taskStatusChanged',\n            'projectInvitation', 'newUser'\n        )\n    )\n)","-- Création d'index pour améliorer les performances\nCREATE INDEX IF NOT EXISTS notifications_user_id_idx ON public.notifications(user_id)","CREATE INDEX IF NOT EXISTS notifications_created_at_idx ON public.notifications(created_at DESC)","CREATE INDEX IF NOT EXISTS notifications_is_read_idx ON public.notifications(is_read)","CREATE INDEX IF NOT EXISTS notifications_related_id_idx ON public.notifications(related_id)","-- Activer RLS (Row Level Security)\nALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY","-- Politique pour permettre aux utilisateurs de voir uniquement leurs propres notifications\nCREATE POLICY \\"Les utilisateurs peuvent voir leurs propres notifications\\" ON public.notifications\n    FOR SELECT\n    USING (user_id = auth.uid())","-- Politique pour permettre aux utilisateurs de marquer leurs propres notifications comme lues\nCREATE POLICY \\"Les utilisateurs peuvent mettre à jour leurs propres notifications\\" ON public.notifications\n    FOR UPDATE\n    USING (user_id = auth.uid())","-- Politique pour permettre aux utilisateurs authentifiés d'insérer des notifications\nCREATE POLICY \\"Les utilisateurs authentifiés peuvent créer des notifications\\" ON public.notifications\n    FOR INSERT\n    WITH CHECK (auth.role() = 'authenticated')","-- Politique pour permettre aux administrateurs de supprimer des notifications\nCREATE POLICY \\"Les administrateurs peuvent supprimer des notifications\\" ON public.notifications\n    FOR DELETE\n    USING (\n        -- Vous pouvez définir ici une condition basée sur un rôle d'administrateur\n        -- Par exemple: auth.uid() IN (SELECT user_id FROM public.admins)\n        -- Pour l'instant, nous autorisons la suppression par le propriétaire\n        user_id = auth.uid()\n    )"}	add_notifications_table
