--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: postgres
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_cron_access() OWNER TO postgres;

--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: postgres
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


ALTER FUNCTION extensions.grant_pg_graphql_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: postgres
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_net_access() OWNER TO postgres;

--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: postgres
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_ddl_watch() OWNER TO supabase_admin;

--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_drop_watch() OWNER TO supabase_admin;

--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION extensions.set_graphql_placeholder() OWNER TO supabase_admin;

--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: postgres
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RAISE WARNING 'PgBouncer auth request: %', p_usename;

    RETURN QUERY
    SELECT usename::TEXT, passwd::TEXT FROM pg_catalog.pg_shadow
    WHERE usename = p_usename;
END;
$$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO postgres;

--
-- Name: accept_team_invitation_by_token(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_team_invitation_by_token(p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_invitation_id uuid;
  v_team_id uuid;
  v_invited_by uuid;
  v_user_id uuid;
  v_role_id uuid;
  v_now timestamp with time zone;
BEGIN
  -- Obtenir l'ID de l'utilisateur courant
  v_user_id := auth.uid();
  
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Utilisateur non connecté';
  END IF;
  
  -- Récupérer les informations de l'invitation
  SELECT id, team_id, invited_by INTO v_invitation_id, v_team_id, v_invited_by
  FROM public.invitations
  WHERE token = p_token
    AND status = 'pending';
    
  IF v_invitation_id IS NULL THEN
    RAISE EXCEPTION 'Aucune invitation en attente trouvée avec ce code';
  END IF;
  
  -- Vérifier si l'invitation est expirée
  IF (SELECT expires_at FROM public.invitations WHERE id = v_invitation_id) < now() THEN
    UPDATE public.invitations SET status = 'expired' WHERE id = v_invitation_id;
    RAISE EXCEPTION 'Cette invitation a expiré';
  END IF;
  
  -- Récupérer l'ID du rôle team_member
  SELECT id INTO v_role_id FROM public.roles WHERE name = 'team_member';
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'Rôle team_member introuvable';
  END IF;
  
  v_now := now();
  
  -- Traitement pour team_members - Approche atomique
  PERFORM id FROM public.team_members 
  WHERE team_id = v_team_id AND user_id = v_user_id;
  
  IF FOUND THEN
    -- Mettre à jour le membre existant
    UPDATE public.team_members
    SET status = 'active', 
        role = 'member',
        joined_at = COALESCE(joined_at, v_now)
    WHERE team_id = v_team_id AND user_id = v_user_id;
  ELSE
    BEGIN
      -- Insérer un nouveau membre
      VALUES (gen_random_uuid(), v_team_id, v_user_id, 'member', 'active', v_invited_by, v_now);
    EXCEPTION WHEN others THEN
      -- Ignorer les erreurs et réessayer avec une mise à jour
      UPDATE public.team_members
      SET status = 'active', 
          role = 'member',
          joined_at = COALESCE(joined_at, v_now)
      WHERE team_id = v_team_id AND user_id = v_user_id;
    END;
  END IF;
  
  -- Traitement pour user_roles - Approche atomique et indépendante
  PERFORM id FROM public.user_roles
  WHERE user_id = v_user_id AND team_id = v_team_id AND role_id = v_role_id;
  
  IF NOT FOUND THEN
    BEGIN
      -- Insérer le rôle uniquement s'il n'existe pas déjà
      VALUES (gen_random_uuid(), v_user_id, v_role_id, v_team_id, NULL, v_invited_by);
    EXCEPTION WHEN others THEN
      -- Si erreur, ignorer (probablement déjà inséré entre-temps)
      NULL;
    END;
  END IF;
  
  -- Mettre à jour le statut de l'invitation
  UPDATE public.invitations
  SET status = 'accepted'
  WHERE id = v_invitation_id;
  
END;
$$;


ALTER FUNCTION public.accept_team_invitation_by_token(p_token text) OWNER TO postgres;

--
-- Name: FUNCTION accept_team_invitation_by_token(p_token text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.accept_team_invitation_by_token(p_token text) IS 'Accepte une invitation d''équipe en utilisant le token d''invitation. 
Cette fonction centralise la logique pour gérer les deux systèmes (legacy et RBAC).';


--
-- Name: add_project_to_team(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_project_to_team(p_team_id uuid, p_project_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_id uuid;
  v_exists boolean;
BEGIN
  -- Vérifier si l'association existe déjà
  SELECT EXISTS (
    SELECT 1 FROM team_projects
    WHERE team_id = p_team_id AND project_id = p_project_id
  ) INTO v_exists;
  
  -- Si l'association n'existe pas, la créer
  IF NOT v_exists THEN
    -- Générer un nouvel UUID
    v_id := gen_random_uuid();
    
    -- Insérer la nouvelle association
    VALUES (v_id, p_team_id, p_project_id);
    
    -- Loguer l'action dans le journal d'audit de PostgreSQL
    RAISE NOTICE 'Team % associated with project %', p_team_id, p_project_id;
  END IF;
END;
$$;


ALTER FUNCTION public.add_project_to_team(p_team_id uuid, p_project_id uuid) OWNER TO postgres;

--
-- Name: allocate_budget_to_project(text, text, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.allocate_budget_to_project(p_budget_id text, p_project_id text, p_amount double precision) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_budget_current_amount double precision;
BEGIN
  -- Vérifier si le budget a suffisamment de fonds
  SELECT current_amount INTO v_budget_current_amount
  FROM budgets
  WHERE id = p_budget_id;
  
  IF v_budget_current_amount < p_amount THEN
    RAISE EXCEPTION 'Budget insuffisant: % disponible, % demandé', v_budget_current_amount, p_amount;
  END IF;
  
  -- Mettre à jour le montant actuel du budget global
  UPDATE budgets
  SET 
    current_amount = current_amount - p_amount,
    updated_at = NOW()
  WHERE id = p_budget_id;
  
  -- Mettre à jour le budget alloué du projet
  UPDATE projects
  SET 
    budget_allocated = COALESCE(budget_allocated, 0) + p_amount,
    updated_at = NOW()
  WHERE id = p_project_id;
  
  -- Insérer une entrée dans la table des allocations budgétaires
    id, 
    budget_id, 
    project_id, 
    amount, 
    allocation_date, 
    created_at, 
    created_by
  )
  VALUES (
    gen_random_uuid(), 
    p_budget_id, 
    p_project_id, 
    p_amount, 
    NOW(), 
    NOW(), 
    auth.uid()
  );
END;
$$;


ALTER FUNCTION public.allocate_budget_to_project(p_budget_id text, p_project_id text, p_amount double precision) OWNER TO postgres;

--
-- Name: assign_user_role(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_user_role(p_user_id uuid, p_role_name text, p_team_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_role_id uuid;
BEGIN
    -- Récupérer l'ID du rôle
    SELECT id INTO v_role_id FROM roles WHERE name = p_role_name;
    
    IF v_role_id IS NULL THEN
        RAISE EXCEPTION 'Rôle non trouvé: %', p_role_name;
    END IF;
    
    -- Insérer le rôle utilisateur
    VALUES (p_user_id, v_role_id, p_team_id, p_project_id)
    ON CONFLICT (user_id, role_id, COALESCE(team_id, '00000000-0000-0000-0000-000000000000'::uuid), 
                COALESCE(project_id, '00000000-0000-0000-0000-000000000000'::uuid))
    DO NOTHING;
    
    RETURN true;
END;
$$;


ALTER FUNCTION public.assign_user_role(p_user_id uuid, p_role_name text, p_team_id uuid, p_project_id uuid) OWNER TO postgres;

--
-- Name: auto_assign_project_to_creator(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_assign_project_to_creator(p_project_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_role_id uuid;
  v_user_role_id uuid;
BEGIN
  -- Rechercher un rôle de l'utilisateur qui a la permission create_project
  SELECT ur.id INTO v_user_role_id
  FROM user_roles ur
  JOIN role_permissions rp ON ur.role_id = rp.role_id
  JOIN permissions p ON rp.permission_id = p.id
  WHERE ur.user_id = p_user_id
  AND p.name = 'create_project'
  LIMIT 1;
  
  -- Si l'utilisateur a un rôle avec la permission create_project
  IF v_user_role_id IS NOT NULL THEN
    -- Vérifier si l'association existe déjà
    IF NOT EXISTS (
      SELECT 1 FROM user_role_projects
      WHERE user_role_id = v_user_role_id AND project_id = p_project_id
    ) THEN
      -- Créer l'association dans user_role_projects
      VALUES (gen_random_uuid(), v_user_role_id, p_project_id);
      
      RAISE NOTICE 'Projet % automatiquement associé à l''utilisateur % via le rôle %', 
        p_project_id, p_user_id, v_user_role_id;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION public.auto_assign_project_to_creator(p_project_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: can_access_project(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_access_project(project_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Admin système
    IF user_has_permission(auth.uid(), 'read_all_projects') THEN
        RETURN true;
    END IF;
    
    -- Chef de projet ou autre rôle avec permission spécifique pour ce projet
    IF user_has_permission(auth.uid(), 'read_project', NULL, project_id) THEN
        RETURN true;
    END IF;
    
    -- Membre d'équipe associée au projet
    RETURN EXISTS (
        SELECT 1 FROM "public"."team_projects" tp
        JOIN "public"."team_members" tm ON tp.team_id = tm.team_id
        WHERE tp.project_id = project_id
        AND tm.user_id = auth.uid()
        AND tm.status = 'active'
    );
END;
$$;


ALTER FUNCTION public.can_access_project(project_id uuid) OWNER TO postgres;

--
-- Name: can_modify_project(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_modify_project(project_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Admin système
    IF user_has_permission(auth.uid(), 'update_project') THEN
        RETURN true;
    END IF;
    
    -- Chef de projet pour ce projet spécifique
    IF user_has_permission(auth.uid(), 'update_project', NULL, project_id) THEN
        RETURN true;
    END IF;
    
    -- Admin d'équipe associée au projet
    RETURN EXISTS (
        SELECT 1 FROM "public"."team_projects" tp
        JOIN "public"."team_members" tm ON tp.team_id = tm.team_id
        WHERE tp.project_id = project_id
        AND tm.user_id = auth.uid()
        AND tm.role = 'admin'
        AND tm.status = 'active'
    );
END;
$$;


ALTER FUNCTION public.can_modify_project(project_id uuid) OWNER TO postgres;

--
-- Name: check_sub_phase_belongs_to_phase(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_sub_phase_belongs_to_phase() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si sub_phase_id est NULL, c'est valide
    IF NEW.sub_phase_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Vérifier que la sous-phase est bien une sous-phase de la phase principale
    IF NOT EXISTS (
        SELECT 1 FROM phases 
        WHERE id = NEW.sub_phase_id AND parent_phase_id = NEW.phase_id
    ) THEN
        RAISE EXCEPTION 'La sous-phase doit appartenir à la phase principale';
    END IF;
    
    RETURN NEW;
END;
$$;


