    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    team_id uuid,
    project_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    created_by uuid
);


ALTER TABLE public.user_roles OWNER TO postgres;

--
-- Name: user_permissions_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.user_permissions_view AS
 SELECT u.id AS user_id,
    u.email,
    p.display_name AS user_name,
    r.name AS role_name,
    r.description AS role_description,
    perm.name AS permission_name,
    perm.resource_type,
    perm.action,
    t.name AS team_name,
    t.id AS team_id,
    pr.name AS project_name,
    pr.id AS project_id
   FROM (((((((auth.users u
     JOIN public.profiles p ON ((u.id = p.id)))
     JOIN public.user_roles ur ON ((u.id = ur.user_id)))
     JOIN public.roles r ON ((ur.role_id = r.id)))
     JOIN public.role_permissions rp ON ((r.id = rp.role_id)))
     JOIN public.permissions perm ON ((rp.permission_id = perm.id)))
     LEFT JOIN public.teams t ON ((ur.team_id = t.id)))
     LEFT JOIN public.projects pr ON ((ur.project_id = pr.id)));


ALTER VIEW public.user_permissions_view OWNER TO postgres;

