--
-- Name: users Temporary allow all operations on users; Type: POLICY; Schema: auth; Owner: supabase_auth_admin
--

CREATE POLICY "Temporary allow all operations on users" ON auth.users USING (true);


--
-- Name: users Users can view team members; Type: POLICY; Schema: auth; Owner: supabase_auth_admin
--

CREATE POLICY "Users can view team members" ON auth.users FOR SELECT USING ((id IN ( SELECT tm.user_id
   FROM public.team_members tm
  WHERE ((tm.team_id IN ( SELECT team_members.team_id
           FROM public.team_members
          WHERE ((team_members.user_id = auth.uid()) AND (team_members.status = 'active'::text)))) AND (tm.status = 'active'::text)))));


--
-- Name: users Users can view their own user data; Type: POLICY; Schema: auth; Owner: supabase_auth_admin
--

CREATE POLICY "Users can view their own user data" ON auth.users FOR SELECT USING ((auth.uid() = id));


--
-- Name: users Users can view users they invited; Type: POLICY; Schema: auth; Owner: supabase_auth_admin
--

CREATE POLICY "Users can view users they invited" ON auth.users FOR SELECT USING ((id IN ( SELECT tm.user_id
   FROM public.team_members tm
  WHERE (tm.invited_by = auth.uid()))));


